update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/toulouse/haute-garonne/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle en Haute-Garonne","mecanisme":"Le département vit au rythme de la sous-traitance aéronautique et spatiale. Autour de Blagnac et de Colomiers, les ateliers d''usinage et de traitement de surface travaillent en flux tendu. Nous avons un hub de techniciens à Toulouse, dans le département, et nos équipes interviennent sur tout le territoire.","cta":"Faire chiffrer ma maintenance en Haute-Garonne","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7, en option, couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"10","libelle":"hubs de techniciens en France, dont celui de Toulouse, dans le département"},{"valeur":"+ 100","libelle":"collaborateurs, mobilisables d''un hub à l''autre selon la spécialité demandée"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"}]},{"type":"probleme","punchline":"En flux tendu aéronautique, une machine d''usinage arrêtée ne retarde pas une pièce. Elle retarde une chaîne d''assemblage entière, et tout le monde saura d''où vient le trou.","puces":[{"accroche":"Votre cadence est dictée par le donneur d''ordre.","texte":"Un rattrapage ne se négocie pas, il se paie en heures supplémentaires et en pénalités."},{"accroche":"Le traitement de surface tolère peu d''écarts.","texte":"Bains, fours, lignes d''application : une dérive non vue devient un lot déclassé."},{"accroche":"La documentation fait partie de la pièce.","texte":"Sans traçabilité de l''intervention, votre dossier qualité ne tient pas devant l''audit."},{"accroche":"Les sites du département sont dispersés.","texte":"Du Muretain au Comminges, un parc éloigné se retrouve vite sans entretien régulier."},{"accroche":"L''agroalimentaire travaille en campagne.","texte":"Conserveries et coopératives n''ont que quelques semaines pour produire, pas pour réparer."}]},{"type":"offre","lignes":[{"prestation":{"texte":"**[Mécanique générale](/expertises/mecanique/)**"},"benefice":"Roulements, réducteurs, alignements, maintenance de machines-outils à commande numérique"},{"prestation":{"texte":"**[Électricité industrielle](/expertises/electrique/)**"},"benefice":"Armoires, moteurs, variateurs, suivi des bobinages, recherche de défaut"},{"prestation":{"texte":"**[Automatisme](/expertises/automatisme/)**"},"benefice":"Automates SIEMENS et Schneider, supervision, remontée d''alertes"},{"prestation":{"texte":"**Hydraulique et pneumatique**"},"benefice":"Centrales, pompes, vérins, distributeurs, chasse aux fuites"},{"prestation":{"texte":"**Soudure et chaudronnerie**"},"benefice":"Châssis, goulottes, tuyauteries, permis de feu et consignations"},{"prestation":{"texte":"**[Robotique](/expertises/robotique/)**"},"benefice":"Robots ABB et Fanuc, trajectoires, changements d''outillage, remise en production"}],"prose":[{"texte":"Pour un moteur en défaut : diagnostic, dépose, bobinage confié à un atelier spécialisé. Le bobinage fait, nous gérons remontage, essais et remise en service. La réparation est testée en charge, pas déclarée bonne sur le papier."}]}]'::jsonb) where path = '/implantations/toulouse/haute-garonne/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"L''appel","texte":"un seul numéro, le 04 78 33 72 05. Décrivez la panne, un chargé d''affaires vous rappelle dans l''heure aux horaires ouvrés."},{"titre":"La qualification","texte":"équipement, criticité, habilitations requises, accès au site. La préparation évite le second déplacement."},{"titre":"Le chiffrage écrit","texte":"périmètre, exclusions, conditions de mobilisation, temps d''arrêt prévu. Le plan de prévention est intégré dès le devis."},{"titre":"L''intervention","texte":"réparation sur site en sécurité, pièces consultées au prix réel, diagnostic."},{"titre":"La remise en production","texte":"essais avec votre exploitation, validation avant de rendre l''installation."},{"titre":"La traçabilité","texte":"compte rendu écrit, historique et seuils d''alerte dans votre GMAO, préconisations pour ajuster les fréquences."}]},{"type":"garanties","puces":[{"accroche":"Une profondeur de métiers, pas une spécialité isolée","texte":"un prestataire seul sur un métier vous laisse nu sur les autres. Mécanique, électricité, automatisme et robotique sont couverts par la même équipe."},{"accroche":"Des intervenants dont vous connaissez le niveau avant l''arrivée","texte":"10 % des candidats retenus, habilitations à jour, résultats d''évaluation transmis."},{"accroche":"Un compte rendu que vous pouvez montrer","texte":"demandez-en un exemple avant de signer. La façon dont l''accueil sécurité et les accès se préparent en dit plus qu''une plaquette."}]},{"type":"cta","question":"Besoin de sécuriser la disponibilité de vos machines d''usinage avant la prochaine montée en cadence ?","bouton":"Faire chiffrer ma maintenance en Haute-Garonne","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"3 à 5 techniciens déployés pour accompagner la montée en cadence de plusieurs usines en France","texte":", depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"},{"titre":"6 techniciens multidisciplinaires pour l''installation et la mise en production d''un nouveau parc machines","texte":", mission toujours en cours","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Un technicien à temps plein sur des centres d''usinage, des presses et des machines à commande numérique","texte":", parc multimarques","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Des intervenants qualifiés intégrés au contrôle de chantier","texte":"d''un spécialiste mondial de l''automatisation, sur des projets d''aéroports et d''industrie","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"},{"titre":"12 monteurs mécaniciens et 8 engins de levage pour le montage d''un centre logistique","texte":"6 semaines de chantier, date de livraison non négociable, tenue","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"}]}]'::jsonb) where path = '/implantations/toulouse/haute-garonne/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Couvrez-vous tout le 31, au-delà de Toulouse ?","reponse":"Oui : Colomiers, Blagnac, Portet-sur-Garonne, Ramonville-Saint-Agne, Labège, Muret, Cugnaux, puis le Lauragais, le Muretain et le Comminges jusqu''à Saint-Gaudens. Hors du département, le maillage national prend le relais, avec les mêmes méthodes et les mêmes rapports."},{"question":"Travaillez-vous pour la sous-traitance aéronautique ?","reponse":"Oui, la cadence nous est familière : usinage, traitement de surface, lignes en flux tendu, documentation exigée. Nous intervenons aussi en chimie et en agroalimentaire dans la région, chaque environnement gardant ses règles propres."},{"question":"Et pour nos sites du Tarn, du Gers ou de l''Ariège ?","reponse":"Nous intervenons dans ces départements comme dans le Tarn-et-Garonne, avec des techniciens qui se déplacent partout en France. Un seul contrat, un seul interlocuteur, une maintenance identique d''un site à l''autre."},{"question":"Quelle formule pour quelle taille de site ?","reponse":"Un atelier de mécanique générale n''a pas les contraintes d''une usine en 3x8. Dépannage à la demande, [contrat Zéro arrêt](/offres/zero-arret/) sur devis, ou technicien en [résidence](/offres/residence/). Le nombre de visites et le périmètre sont écrits noir sur blanc."},{"question":"Intervenez-vous en urgence partout dans le département ?","reponse":"En journée, nos équipes organisent l''intervention corrective, le technicien arrivant avec le contexte déjà connu. Le reste est couvert par l''astreinte 24/24 et 7/7, garantie par contrat, en option."},{"question":"Comment préparez-vous un arrêt technique ?","reponse":"Le projet démarre à J-90 et se verrouille à J-30 : périmètre, moyens, plan de charge, coactivité. La restitution se fait à la demi-journée. Les grands travaux d''un [arrêt technique](/offres/arret-technique/) se gagnent avant de commencer."}]},{"type":"ctaFinal","question":"Besoin d''un prestataire qui couvre toutes vos spécialités, pas une seule ?","bouton":"Faire chiffrer ma maintenance en Haute-Garonne","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/toulouse/haute-garonne/';
